/// <summary>
/// <c>METDeliveryNoteReportDP</c> class holds the logic to run the delivery note report
/// </summary>
[SrsReportParameterAttribute(classStr(METDeliveryNoteReportContract))]
public class METDeliveryNoteReportDP extends SrsReportDataProviderPreProcessTempDB
{
    METDeliveryNoteReportHeaderTmp      headerTableTmp;
    METDeliveryNoteReportLineTmp        lineTableTmp;
    RecordInsertList                    headerTableList;
    RecordInsertList                    lineTableList;
    Qty                                 cartons;
    Qty                                 kegs;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// method to get data of table METDeliveryNoteReportHeaderTmp
/// </summary>
/// <returns>METDeliveryNoteReportHeaderTmp</returns>
[SrsReportDataSetAttribute('METDeliveryNoteReportHeaderTmp')]
public METDeliveryNoteReportHeaderTmp getHeaderData()
{
    select * from headerTableTmp;
    return headerTableTmp;
}

/// <summary>
/// method to get data of table METDeliveryNoteReportLineTmp
/// </summary>
/// <returns>METDeliveryNoteReportLineTmp</returns>
[SrsReportDataSetAttribute('METDeliveryNoteReportLineTmp')]
public METDeliveryNoteReportLineTmp getLineData()
{
    select * from lineTableTmp;
    return lineTableTmp;
}

/// <summary>
/// Logic to run the report
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     soShipmentHeader;
    METSalesOrderShipmentLoadLines      soShipmentLine;
    SalesTable                          salesTable;
    container                           conSalesId;

    METDeliveryNoteReportContract       contract = this.parmDataContract();

    WHSShipmentId   shipmentId     = contract.parmShipmentID();

    headerTableList = new RecordInsertList(tableNum(METDeliveryNoteReportHeaderTmp), true, true, true, true, true, headerTableTmp);

    select firstonly soShipmentHeader
        where soShipmentHeader.ShipmentId == shipmentId
        join soShipmentLine
            where soShipmentLine.ShipmentId == soShipmentHeader.shipmentid
            join salesTable
                where salesTable.SalesId == soShipmentLine.OrderNum;
    {
        headerTableTmp.clear();

        InventLocation          inventLocationSO    = InventLocation::find(salesTable.InventLocationId);
        InventLocation          inventLocationShip  = InventLocation::find(soShipmentHeader.Warehouse);
        METIndustryKeyTable     industryKey         = METIndustryKeyTable::find(inventLocationSO.METWHSubEntity);
        METSalesTable           metSalesTable       = METSalesTable::findByRefRecId(salesTable.RecId);
        SysDocuBrandDetails     docuBrandingDetails = this.getDocuBrandingDetails(inventLocationShip.METWHSubEntity);

        // Task 226480: Branding details update - Reports - Start
        //headerTableTmp.Logo                 = SysDocuBrandImages::getImage(inventLocationSO.METWHSubEntity);
        headerTableTmp.IndustryKey          = industryKey.IndustryKey;
        // Task 226480: Branding details update - Reports - End
        headerTableTmp.CompanyName          = industryKey.CompanyName;
        headerTableTmp.ABN                  = METIndustryKeyTable::find(inventLocationShip.METWHSubEntity).CoRegNum;
        headerTableTmp.WarehouseName        = inventLocationSO.Name;
        headerTableTmp.WarehouseAddress     = inventLocationSO.address();
        headerTableTmp.DeliveryName         = soShipmentHeader.displayCustName();
        headerTableTmp.DeliveryAddress      = salesTable.deliveryAddressing();
        headerTableTmp.DeliveryDocNo        = shipmentId;
        headerTableTmp.DlvInstruction       = metSalesTable.DeliveryInstructions;
        headerTableTmp.ShipConfirmDate      = soShipmentHeader.ConfirmedShipDate;
        headerTableTmp.CustAccount          = soShipmentHeader.CustAccount;

        conSalesId = this.getReturnSO(soShipmentHeader.CustAccount);

        headerTableTmp.SalesId              = conLen(conSalesId) > 1 ? METConstants::Multiple : salesTable.SalesId;
        headerTableTmp.RouteStop            = strFmt("@MET:METStringBackSlash",soShipmentHeader.Route,soShipmentHeader.RouteStopNum);
        headerTableTmp.Pickup               = con2Str(conSalesId);
        headerTableTmp.Phone                = docuBrandingDetails.Phone;
        headerTableTmp.Email                = docuBrandingDetails.Email;

        if(!conFind(conSalesId, salesTable.SalesId))
        {
            conSalesId  += salesTable.SalesId;
        }
        this.initializeLine(shipmentId);

        headerTableTmp.Cartons              = cartons;
        headerTableTmp.Kegs                 = kegs;

        headerTableTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        headerTableTmp.DeliveryNotesHeaderGuidStr = headerReportGuid;

        headerTableList.add(headerTableTmp);

    }
    headerTableList.insertDatabase();
}

/// <summary>
/// method initialize the line table
/// </summary>
/// <param name = "_shipmentId">WHSShipmentId</param>
protected void initializeLine(WHSShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadLines      soShipmentLineLoc;

    lineTableList = new RecordInsertList(tableNum(METDeliveryNoteReportLineTmp), true, true, true, true, true, lineTableTmp);

    while select soShipmentLineLoc
        where soShipmentLineLoc.ShipmentId == _shipmentId
    {
        InventTable     inventTableloc  = InventTable::find(soShipmentLineLoc.ItemId);
        SalesLine       salesLineLoc = SalesLine::find(soShipmentLineLoc.OrderNum, soShipmentLineLoc.LineNum);

        lineTableTmp.SalesId            = soShipmentLineLoc.OrderNum;
        lineTableTmp.ItemId             = soShipmentLineLoc.ItemId;
        lineTableTmp.ItemDescription    = EcoResProductTranslation::findByProductLanguage(inventTableloc.Product,SystemParameters::getSystemLanguageId()).Description;
        lineTableTmp.UOM                = salesLineLoc.SalesUnit;
        lineTableTmp.Qty                = soShipmentLineLoc.PickedQty;

        if(this.isItemSubcomodityCodeExist(inventTableloc.Product))
        {
            kegs    += soShipmentLineLoc.PickedQty;
        }
        else if(inventTableloc.salesUnitId() like METConstants::UOMOuterMultiple)
        {
            cartons += soShipmentLineLoc.PickedQty;
        }

        lineTableTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        lineTableTmp.DeliveryNotesHeaderGuidStr = headerReportGuid;

        lineTableList.add(lineTableTmp);
    }

    lineTableList.insertDatabase();
}

/// <summary>
/// method to check the comodity code for item in the parameter
/// </summary>
/// <param name = "_product">RefRecId</param>
/// <returns>boolean</returns>
protected boolean isItemSubcomodityCodeExist(RefRecId _product)
{
    EcoResProductCategory       ecoResProductCategory;
    EcoResCategory              ecoResCategory;
    METSubComodityCode          metSubComodityCode;

    while select ecoResProductCategory
        where ecoResProductCategory.Product == _product
        join ecoResCategory
            where ecoResCategory.RecId == ecoResProductCategory.Category
            join metSubComodityCode
                where metSubComodityCode.Code == ecoResCategory.Code
    {
        return true;
    }

    return false;
}

/// <summary>
/// method to get the list of sales return order for the customer
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <returns>container</returns>
protected container getReturnSO(CustAccount _custAccount)
{
    SalesTable      salesTableReturn;
    container       conSalesId;

    while select salesTableReturn
        where salesTableReturn.SalesType == SalesType::ReturnItem &&
            salesTableReturn.CustAccount == _custAccount
    {
        conSalesId += salesTableReturn.SalesId;
    }

    return conSalesId;
}

/// <summary>
/// Get the branding details information
/// </summary>
/// <param name = "_industryKey">METIndustryKey</param>
/// <returns>SysDocuBrandDetails</returns>
protected SysDocuBrandDetails getDocuBrandingDetails(METIndustryKey _industryKey)
{
    SysDocuBrandDetails     docuBrandingDetails;

    select firstonly docuBrandingDetails
        where docuBrandingDetails.METIndustryKey == _industryKey &&
        docuBrandingDetails.ReportName == METConstants::DeliveryNote;

    return docuBrandingDetails;
}
